import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Профили, друзья и союзы","description":"","frontmatter":{"pageId":"players/community","contentRevision":1},"headers":[],"relativePath":"ru/players/community.md","filePath":"ru/players/community.md"}'),l={name:"ru/players/community.md"};function o(n,a,s,c,d,m){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="профили-друзья-и-союзы" tabindex="-1">Профили, друзья и союзы <a class="header-anchor" href="#профили-друзья-и-союзы" aria-label="Permalink to &quot;Профили, друзья и союзы&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>В <strong>Игроки → Социальное</strong> отредактируй биографию, настройки приглашений и уведомлений. Найди игрока, отправь приглашение дружбы или создай/вступи в союз. Владелец союза приглашает участников, передаёт владение или распускает группу. Чат союза виден текущим участникам с момента вступления, не пересылается в Discord.</p><p>Казна принимает взносы из кошелька. Владелец назначает дневные лимиты вывода; расход считается за сутки UTC и не сбрасывается выходом/повторным вступлением. Уход не возвращает взнос; при роспуске весь остаток получает текущий владелец. Передавай владение осознанно.</p><p>Союзники защищены от взаимных вредных нападений и событий. Вступление при конфликтующей очереди может быть отклонено.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Биография 500 символов; каталог до 200 игроков, 100 друзей, 16 членов союза, один союз на игрока. Приглашения 7 дней, до 32 входящих/исходящих. Транзакция до 1 млрд, казна до 1 трлн. Заморозка/долг/угроза участников может запрещать вывод.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./chat-pings">Чат, сообщения и пинги</a></li><li><a href="./guild-influence">Влияние гильдий</a></li><li><a href="./economy">Кошелёк, почта и рынок</a></li></ul>',10)])])}const h=e(l,[["render",o]]);export{p as __pageData,h as default};
